import{_ as r,o as e,c as l,a2 as t}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"Discord 客服系統","description":"如果你有任何事情需要我們協助，請使用此管道與我們聯繫。","frontmatter":{"title":"Discord 客服系統","description":"如果你有任何事情需要我們協助，請使用此管道與我們聯繫。"},"headers":[],"relativePath":"discord/customer_service/index.md","filePath":"discord/customer_service.md"}'),a={name:"discord/customer_service/index.md"};function s(o,i,c,d,h,n){return e(),l("div",null,[...i[0]||(i[0]=[t('<h1 id="客服系統" tabindex="-1">客服系統 <a class="header-anchor" href="#客服系統" aria-label="Permalink to &quot;客服系統&quot;">​</a></h1><p>如果你有任何事情需要我們協助，請使用此管道與我們聯繫，我們會盡快回覆</p><ul><li>下列事務有指定的申請管道，請點擊連結查看相關說明，不要使用客服系統 <ul><li><a href="/apply/report/">檢舉回報</a>(<b>私人檢舉</b>仍請使用客服系統)</li><li><a href="/apply/form_shop/">商店街事務</a></li><li><a href="/apply/form_paint/">畫作同步</a></li></ul></li><li>若有<b>疑問與開發建議</b>也可以直接在伺服Discord<a href="/discord/text_channel/">提問與開發</a>頻道發問</li></ul><h2 id="使用方式-discord內" tabindex="-1">使用方式(Discord內) <a class="header-anchor" href="#使用方式-discord內" aria-label="Permalink to &quot;使用方式(Discord內)&quot;">​</a></h2><ol><li>請<a href="/discord/">加入伺服Discord</a></li><li>請在左側頻道列表<b>往下滑動至最底</b>並點選<b>客服系統</b>(<a href="https://i.imgur.com/Vd9khPr.gif" target="_blank" rel="noreferrer">操作說明動畫</a>)<br><img src="https://i.imgur.com/wiARUUs.png" style="width:35%;"></li><li>請點擊按鈕<b>點我開啟客服</b><br><img src="https://i.imgur.com/1gsZmYv.png" style="width:50%;"><br><img src="https://i.imgur.com/NAjNlvH.png" style="width:50%;"></li><li>完成後左側選單最下方就會出現一個你專屬的<b>客服頻道</b>了<br><img src="https://i.imgur.com/jIogC9Z.png" style="width:35%;"></li><li>請在此頻道提出你想詢問的問題/要申請的事務等，並等候伺服人員回覆訊息<br><img src="https://i.imgur.com/8HOXj6d.png" style="width:50%;"></li></ol><h2 id="使用方式-遊戲內" tabindex="-1">使用方式(遊戲內) <a class="header-anchor" href="#使用方式-遊戲內" aria-label="Permalink to &quot;使用方式(遊戲內)&quot;">​</a></h2><ul><li>輸入<code>/msc &lt;訊息&gt;</code>將訊息發送至客服系統(若客服頻道不存在會立即建立) <ul><li>須將遊戲帳號<a href="/discord/">綁定Discord帳號</a></li><li>如尚未建立客服頻道會立即開啟</li><li>訊息會在遊戲內及Discord中同步<br><img src="https://i.imgur.com/iyECKjU.png" style="width:80%;"></li></ul></li></ul><h2 id="注意事項" tabindex="-1">注意事項 <a class="header-anchor" href="#注意事項" aria-label="Permalink to &quot;注意事項&quot;">​</a></h2><ul><li>請不要濫用客服系統</li><li>請不要使用客服系統問伺服人員跟伺服完全沒關係的問題</li><li>客服頻道會在使用完成後刪除頻道，若有需要<b>請自行保存紀錄</b></li></ul><div class="warning custom-block"><p class="custom-block-title">客服紀錄公開</p><p><b>伺服方保有將客服紀錄公開的權利</b>，必要時伺服方得<b>向全體玩家公開</b>相關紀錄</p></div>',10)])])}const u=r(a,[["render",s]]);export{p as __pageData,u as default};
